    let p1 = project2(points[p1], plane);
    let q0 = project2(points[q0], plane);
    let q1 = project2(points[q1], plane);
    let p_q0 = robust::orient2d(p0, p1, q0);
    let p_q1 = robust::orient2d(p0, p1, q1);
    let q_p0 = robust::orient2d(q0, q1, p0);
    let q_p1 = robust::orient2d(q0, q1, p1);
